import{_ as s,c as p,o as e,b0 as n}from"./chunks/framework.JcZxIv1X.js";const t="/computer-docs/assets/image-20251021105504683.U2t8RSpN.png",i="/computer-docs/assets/image-20251014152243294.CJ7pqg6v.png",l="/computer-docs/assets/image-20251014152401957.COo9ZEti.png",r="/computer-docs/assets/image-20251014155034134.BQ5qfwvD.png",o="/computer-docs/assets/image-20251014155154406.B9S60xxa.png",d="/computer-docs/assets/image-20251014161926539.B5n80cBB.png",c="/computer-docs/assets/image-20251014170858597.Bxpw-1y_.png",m="/computer-docs/assets/image-20251014171102310.jz9WkXEY.png",b="/computer-docs/assets/image-20251014171828847.B02FPE90.png",u="data:image/png;base64,",h="/computer-docs/assets/image-20251014172035685.BdGGXOxk.png",g="/computer-docs/assets/image-20251014172314984.BhEeI0ti.png",P="/computer-docs/assets/image-20251014201546690.CeMA_sX4.png",C="/computer-docs/assets/image-20251014201902680.BTS14iEm.png",H="/computer-docs/assets/image-20251014201920364.2xHqin9U.png",x="/computer-docs/assets/image-20251014201932356.Fh1OEyTQ.png",v="/computer-docs/assets/image-20251014201944020.BdhYUhaE.png",A="/computer-docs/assets/image-20251014201959757.oDc2rzL3.png",B="/computer-docs/assets/image-20251014202016628.kNjdj3mS.png",U="/computer-docs/assets/image-20251014202033492.BIzEZtij.png",q="/computer-docs/assets/image-20251014202046408.BQLPAswg.png",I="/computer-docs/assets/image-20251014202102476.CXQqlwM-.png",k="/computer-docs/assets/image-20251014202431149.DMge0JDA.png",X="/computer-docs/assets/image-20251014202445709.sLOlbrpB.png",y="/computer-docs/assets/image-20251014202457284.D5JXzJaF.png",S="/computer-docs/assets/image-20251014202510596.CS02YEHt.png",E="/computer-docs/assets/image-20251014202528907.CHmb0DUG.png",F="/computer-docs/assets/image-20251014202547100.DW75TIW2.png",_="/computer-docs/assets/image-20251014202606213.BR0K-Cyr.png",f="/computer-docs/assets/image-20251015091708381.DooFcFoO.png",z=JSON.parse('{"title":"LV002-第2章-寄存器","description":null,"frontmatter":{"title":"LV002-第2章-寄存器","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93b6468bcc82c","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.950Z","fulluuid":"468bcc82c30e4597ab393b9ca28154ec","useduuid":"468bcc82c"}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93b6468bcc82c.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV002-第2章-寄存器.md","lastUpdated":1767424849000}'),D={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93b6468bcc82c.md"};function w(j,a,G,K,L,Q){return e(),p("div",null,[...a[0]||(a[0]=[n('<h1 id="lv002-第2章-寄存器" tabindex="-1">LV002-第2章-寄存器 <a class="header-anchor" href="#lv002-第2章-寄存器" aria-label="Permalink to &quot;LV002-第2章-寄存器&quot;">​</a></h1><h2 id="_2-1-通用寄存器" tabindex="-1">2.1 通用寄存器 <a class="header-anchor" href="#_2-1-通用寄存器" aria-label="Permalink to &quot;2.1 通用寄存器&quot;">​</a></h2><p>8086CPU 的所有寄存器都是 16 位的, 可以存放两个字节。AX、BX、CX、DX 这 4 个寄存器通常用来存放一般性的数据, 被称为通用寄存器。</p><p>以 AX 为例, 寄存器的逻辑结构如图 2.1 所示。</p><p><img src="'+t+'" alt="image-20251021105504683"></p><p>一个 16 位寄存器可以存储一个 16 位的数据, 数据在寄存器中的存放情况如图 2.2 所示。</p><p><img src="'+i+'" alt="image-20251014152243294"></p><p>想一想, 一个 16 位寄存器所能存储的数据的最大值为多少?</p><p>8086CPU 的上一代 CPU 中的寄存器都是 8 位的, 为了保证兼容, 使原来基于上代 CPU 编写的程序稍加修改就可以运行在 8086 之上, 8086CPU 的 AX、BX、CX、DX 这 4 个寄存器都可分为两个可独立使用的 8 位寄存器来用:</p><ul><li>AX 可分为 AH 和 AL；</li><li>BX 可分为 BH 和 BL；</li><li>CX 可分为 CH 和 CL；</li><li>DX 可分为 DH 和 DL。</li></ul><p>以 AX 为例，8086CPU 的 16 位寄存器分为两个 8 位寄存器的情况如图 2.3 所示。</p><img src="'+l+'" alt="image-20251014152401957" style="zoom:67%;"><p>AX 的低 8 位（0 位~7 位）构成了 AL 寄存器，高 8 位（8 位~15 位）构成了 AH 寄存器。AH 和 AL 寄存器是可以独立使用的 8 位寄存器。图 2.4 展示了 16 位寄存器及它所分成的两个 8 位寄存器的数据存储的情况。</p><img src="'+r+'" alt="image-20251014155034134" style="zoom:80%;"><p>想一想，一个 8 位寄存器所能存储的数据的最大值为多少？</p><h2 id="_2-2-字在寄存器中的存储" tabindex="-1">2.2 字在寄存器中的存储 <a class="header-anchor" href="#_2-2-字在寄存器中的存储" aria-label="Permalink to &quot;2.2 字在寄存器中的存储&quot;">​</a></h2><p>出于对兼容性的考虑,8086CPU 可以一次性处理以下两种尺寸的数据。</p><ul><li>字节: 记为 byte, 一个字节由 8 个 bit 组成, 可以存在 8 位寄存器中。</li><li>字: 记为 word, 一个字由两个字节组成, 这两个字节分别称为这个字的高位字节和低位字节, 如图 2.5 所示。</li></ul><p><img src="'+o+'" alt="image-20251014155154406"></p><p>一个字可以存在一个 16 位寄存器中，这个字的高位字节和低位字节自然就存在这个寄存器的高 8 位寄存器和低 8 位寄存器中。如图 2.4 所示，一个字型数据 20000，存在 AX 寄存器中，在 AH 中存储了它的高 8 位，在 AL 中存储了它的低 8 位。AH 和 AL 中的数据，既可以看成是一个字型数据的高 8 位和低 8 位，这个字型数据的大小是 20000；又可以看成是两个独立的字节型数据，它们的大小分别是 78 和 32。</p><blockquote><p>Tips：关于数制的讨论</p><p>任何数据，到了计算机中都是以二进制的形式存放的。为了描述不同的问题，又经常将它们用其他的进制来表示。比如图 2.4 中寄存器 AX 中的数据是 0100111000100000，这就是读 AX 中的信息本身，可以用不同的逻辑意义来看待它。可以将它看作一个数值，大小是 20000。</p><p>当然, 二进制数 0100111000100000 本身也可表示一个数值的大小, 但人类习惯的是十进制, 用十进制 20000 表示可以使我们直观地感受到这个数值的大小。</p><p>十六进制数的一位相当于二进制数的四位, 如 0100111000100000 可表示成: 4(0100)、E(1110)、2(0010)、0(0000)四位十六进制数。</p><p>由于一个内存单元可存放 8 位数据, CPU 中的寄存器又可存放 n 个 8 位的数据。也就是说, 计算机中的数据大多是由 1~N 个 8 位数据构成的。很多时候, 需要直观地看出组成数据的各个字节数据的值, 用十六进制来表示数据可以直观地看出这个数据是由哪些 8 位数据构成的。比如 20000 写成 4E20 就可以直观的看出，这个数据是由 4E 和 20 两个 8 位数据构成的, 如果 AX 中存放 4E20, 则 AH 里是 4E, AL 里是 20。这种表示方法便于许多问题的直观分析。在以后的课程中, 我们多用十六进制来表示一个数据。</p><p>在以后的课程中, 为了区分不同的进制, 在十六进制表示的数据的后面加 H, 在二进制表示的数据后面加 B, 十进制表示的数据后面什么也不加。如: 可用 3 种不同的进制表示图 2.4 中 AX 里的数据, 十进制: 20000, 十六进制: 4E20H, 二进制: 0100111000100000B。</p></blockquote><h2 id="_2-3-几条汇编指令" tabindex="-1">2.3 几条汇编指令 <a class="header-anchor" href="#_2-3-几条汇编指令" aria-label="Permalink to &quot;2.3 几条汇编指令&quot;">​</a></h2><p>通过汇编指令控制 CPU 进行工作，看一下表 2.1 中的几条指令。</p><p align="center"> 表 2.1 汇编指令举例 </p><table tabindex="0"><thead><tr><th>汇编指令</th><th>控制 CPU 完成的操作</th><th>用高级语言的语法描述</th></tr></thead><tbody><tr><td>mov ax,18</td><td>将 18 送入寄存器 AX</td><td>AX = 18</td></tr><tr><td>mov ah,78</td><td>将 78 送入寄存器 AH</td><td>AH = 78</td></tr><tr><td>add ax,8</td><td>将寄存器 AX 中的数值加上 8</td><td>AX = AX+8</td></tr><tr><td>mov ax, bx</td><td>将寄存器 BX 中的数据送入寄存器 AX</td><td>AX = BX</td></tr><tr><td>add ax, bx</td><td>将 AX 和 BX 中的数值相加，结果存在 AX 中</td><td>AX = AX+BX</td></tr></tbody></table><p>注意, 为了使具有高级语言基础的读者更好地理解指令的含义, 有时会用文字描述和高级语言描述这两种方式来描述一条汇编指令的含义。在写一条汇编指令或一个寄存器的名称时不区分大小写。 如: mov ax,18 和 MOV AX,18 的含义相同; bx 和 BX 的含义相同。</p><p>接下来看一下 CPU 执行表 2.2 中所列的程序段中的每条指令后, 对寄存器中的数据进行的改变。</p><p align="center"> 表 2.2 程序段中指令的执行情况之一（原 AX 中的值：0000H，原 BX 中的值：0000H）</p><table tabindex="0"><thead><tr><th>程序段中的指令</th><th>指令执行后 AX 中的数据</th><th>指令执行后 BX 中的数据</th></tr></thead><tbody><tr><td>mov ax,4E20H</td><td>4E20H</td><td>0000H</td></tr><tr><td>add ax,1406H</td><td>6226H</td><td>0000H</td></tr><tr><td>mov bx,2000H</td><td>6226H</td><td>2000H</td></tr><tr><td>add ax, bx</td><td>8226H</td><td>2000H</td></tr><tr><td>mov bx, ax</td><td>8226H</td><td>8226H</td></tr><tr><td>add ax, bx</td><td>？ （参见问题 2.1）</td><td>8226H</td></tr></tbody></table><h3 id="问题-2-1" tabindex="-1">问题 2.1 <a class="header-anchor" href="#问题-2-1" aria-label="Permalink to &quot;问题 2.1&quot;">​</a></h3><ul><li>问题 2.1：指令执行后 AX 中的数据为多少?思考后看分析。</li></ul><p>分析:</p><p>程序段中的最后一条指令 add ax, bx, 在执行前 ax 和 bx 中的数据都为 8226H, 相加后所得的值为: 1044CH, 但是 ax 为 16 位寄存器, 只能存放 4 位十六进制的数据, 所以最高位的 1 不能在 ax 中保存, ax 中的数据为: 044CH。</p><p>表 2.3 中所列的一段程序的执行情况。</p><p><img src="'+d+`" alt="image-20251014161926539"></p><h3 id="问题-2-2" tabindex="-1">问题 2.2 <a class="header-anchor" href="#问题-2-2" aria-label="Permalink to &quot;问题 2.2&quot;">​</a></h3><ul><li>问题 2.2：指令执行后 AX 中的数据为多少?思考后看分析。</li></ul><p>分析：</p><p>程序段中的最后一条指令 add al，93H，在执行前，al 中的数据为 C5H，相加后所得的值为：158H（0001 0101 1000），但是 al 为 8 位寄存器，只能存放两位十六进制的数据（58H），所以最高位的 1 丢失，ax 中的数据为：0058H。（这里的丢失，指的是进位值不能在 8 位寄存器中保存，但是 CPU 并不真的丢弃这个进位值，关于这个问题，我们将在后面的课程中讨论。）</p><p>注意, 此时 al 是作为一个独立的 8 位寄存器来使用的, 和 ah 没有关系, CPU 在执行这条指令时认为 ah 和 al 是两个不相关的寄存器。不要错误地认为, 诸如 add al,93H 的指令产生的进位会存储在 ah 中, add al,93H 进行的是 8 位运算。</p><p>如果执行 add ax,93H, 低 8 位的进位会存储在 ah 中, CPU 在执行这条指令时认为只有一个 16 位寄存器 ax, 进行的是 16 位运算。 指令 add ax,93H 执行后, ax 中的值为: 0158H。 此时, 使用的寄存器是 16 位寄存器 ax, add ax,93H 相当于将 ax 中的 16 位数据 00c5H 和另一个 16 位数据 0093H 相加, 结果是 16 位的 0158H。</p><p>在进行数据传送或运算时, 要注意指令的两个操作对象的位数应当是一致的, 例如:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,bx</span></span>
<span class="line"><span>mov bx,cx</span></span>
<span class="line"><span>mov ax,18H</span></span>
<span class="line"><span>mov al,18H</span></span>
<span class="line"><span>add ax,bx</span></span>
<span class="line"><span>add ax,20000</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>等都是正确的指令, 而:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,bl    ; (在8位寄存器和16位寄存器之间传送数据)</span></span>
<span class="line"><span>mov bh,ax    ; (在16位寄存器和8位寄存器之间传送数据)</span></span>
<span class="line"><span>mov al,20000 ; (8位寄存器最大可存放值为255的数据)</span></span>
<span class="line"><span>add al,100H  ; (将一个高于8位的数据加到一个8位寄存器中)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>等都是错误的指令, 错误的原因都是指令的两个操作对象的位数不一致。</p><h3 id="检测点-2-1" tabindex="-1">检测点 2.1 <a class="header-anchor" href="#检测点-2-1" aria-label="Permalink to &quot;检测点 2.1&quot;">​</a></h3><p>(1)写出每条汇编指令执行后相关寄存器中的值。</p><table tabindex="0"><thead><tr><th>汇编指令</th><th>寄存器中的值</th></tr></thead><tbody><tr><td>mov ax, 62627</td><td>AX = <code>F4A3H</code></td></tr><tr><td>mov ah, 31H</td><td>AX = <code>31A3H</code></td></tr><tr><td>mov al, 23H</td><td>AX = <code>3123H</code></td></tr><tr><td>add ax, ax</td><td>AX = <code>6246H</code></td></tr><tr><td>mov bx, 826CH</td><td>BX = <code>826CH</code></td></tr><tr><td>mov cx, ax</td><td>CX = <code>6246H</code></td></tr><tr><td>mov ax, bx</td><td>AX = <code>826CH</code></td></tr><tr><td>add ax, bx</td><td>AX = <code>04D8H</code></td></tr><tr><td>mov al, bh</td><td>AX = <code>0482H</code></td></tr><tr><td>mov ah, bl</td><td>AX = <code>6C82H</code></td></tr><tr><td>add ah, ah</td><td>AX = <code>D882H</code></td></tr><tr><td>add al, 6</td><td>AX = <code>D888H</code></td></tr><tr><td>add al, al</td><td>AX = <code>D810H</code></td></tr><tr><td>mov ax, cx</td><td>AX = <code>6246H</code></td></tr></tbody></table><p>(2)只能使用目前学过的汇编指令，最多使用 4 条指令，编程计算 2 的 4 次方。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax, 2</span></span>
<span class="line"><span>add ax, ax</span></span>
<span class="line"><span>add ax, ax</span></span>
<span class="line"><span>add ax, ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="_2-4-物理地址" tabindex="-1">2.4 物理地址 <a class="header-anchor" href="#_2-4-物理地址" aria-label="Permalink to &quot;2.4 物理地址&quot;">​</a></h2><p>我们知道, CPU 访问内存单元时, 要给出内存单元的地址。所有的内存单元构成的存储空间是一个一维的线性空间, 每一个内存单元在这个空间中都有唯一的地址, 我们将这个唯一的地址称为物理地址。</p><p>CPU 通过地址总线送入存储器的, 必须是一个内存单元的物理地址。在 CPU 向地址总线上发出物理地址之前, 必须要在内部先形成这个物理地址。不同的 CPU 可以有不同的形成物理地址的方式。我们现在讨论 8086CPU 是如何在内部形成内存单元的物理地址的。</p><h2 id="_2-5-16-位结构-cpu" tabindex="-1">2.5 16 位结构 CPU <a class="header-anchor" href="#_2-5-16-位结构-cpu" aria-label="Permalink to &quot;2.5 16 位结构 CPU&quot;">​</a></h2><p>我们说 8086CPU 的上一代 CPU（8080、8085）等是 8 位机，而 8086 是 16 位机，也可以说 8086 是 16 位结构的 CPU。那么什么是 16 位结构的 CPU 呢？</p><p>概括地讲，16 位结构（16 位机、字长为 16 位等常见说法，与 16 位结构的含义相同）描述了一个 CPU 具有下面几方面的结构特性。</p><ul><li><p>运算器一次最多可以处理 16 位的数据；</p></li><li><p>寄存器的最大宽度为 16 位；</p></li><li><p>寄存器和运算器之间的通路为 16 位。</p></li></ul><p>8086 是 16 位结构的 CPU，这也就是说，在 8086 内部，能够一次性处理、传输、暂时存储的信息的最大长度是 16 位的。内存单元的地址在送上地址总线之前，必须在 CPU 中处理、传输、暂时存放，对于 16 位 CPU，能一次性处理、传输、暂时存储 16 位的地址。</p><h2 id="_2-6-8086cpu-怎么给出物理地址" tabindex="-1">2.6 8086CPU 怎么给出物理地址？ <a class="header-anchor" href="#_2-6-8086cpu-怎么给出物理地址" aria-label="Permalink to &quot;2.6 8086CPU 怎么给出物理地址？&quot;">​</a></h2><p>8086CPU 有 20 位地址总线, 可以传送 20 位地址, 达到 1MB 寻址能力。8086CPU 又是 16 位结构, 在内部一次性处理、传输、暂时存储的地址为 16 位。从 8086CPU 的内部结构来看, 如果将地址从内部简单地发出, 那么它只能送出 16 位的地址, 表现出的寻址能力只有 64KB。</p><p>8086CPU 采用一种在内部用两个 16 位地址合成的方法来形成一个 20 位的物理地址。8086CPU 相关部件的逻辑结构如图 2.6 所示。</p><p><img src="`+c+'" alt="image-20251014170858597"></p><p>如图 2.6 所示，当 8086CPU 要读写内存时：</p><p>（1）CPU 中的相关部件提供两个 16 位的地址，一个称为段地址，另一个称为偏移地址：</p><p>（2）段地址和偏移地址通过内部总线送入一个称为地址加法器的部件；</p><p>（3）地址加法器将两个 16 位地址合成为一个 20 位的物理地址；</p><p>（4）地址加法器通过内部总线将 20 位物理地址送入输入输出控制电路；</p><p>（5）输入输出控制电路将 20 位物理地址送上地址总线；</p><p>（6）20 位物理地址被地址总线传送到存储器。</p><p>地址加法器采用 <strong>物理地址 = 段地址 x16+偏移地址</strong> 的方法用 <strong>段地址和偏移地址合成物理地址</strong>。例如，8086CPU 要访问地址为 123C8H 的内存单元，此时，地址加法器的工作过程如图 2.7 所示（图中数据皆为十六进制表示）。</p><p><img src="'+m+`" alt="image-20251014171102310"></p><blockquote><p>Tips：由段地址 x16 引发的讨论</p><p>&quot;段地址 x16&quot; 有一个更为常用的说法是左移 4 位。计算机中的所有信息都是以二进制的形式存储的，段地址当然也不例外。机器只能处理二进制信息，&quot;左移 4 位&quot; 中的位，指的是二进制位。</p><p>我们看一个例子，一个数据为 2H，二进制形式为 10B，对其进行左移运算：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">左移位数    二进制  十六进制 十进制</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">0          10B     2H       2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1         100B     4H       4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2        1000B     8H       8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3       10000B    10H      16</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4      100000B    20H      32</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>观察上面移位次数和各种形式数据的关系, 我们可以发现:</p><p>（1）一个数据的二进制形式左移 1 位, 相当于该数据乘以 2;</p><p>（2）一个数据的二进制形式左移 N 位, 相当于该数据乘以 2 的 N 次方;</p><p>（3）地址加法器如何完成段地址 x16 的运算?就是将以二进制形式存放的段地址左移 4 位。</p><p>进一步思考, 我们可看出: 一个数据的十六进制形式左移 1 位, 相当于乘以 16; 一个数据的十进制形式左移 1 位, 相当于乘以 10; 一个 X 进制的数据左移 1 位, 相当于乘以 X。</p></blockquote><h2 id="_2-7-段地址-×16-偏移地址-物理地址-的本质含义" tabindex="-1">2.7 “段地址 ×16 + 偏移地址 = 物理地址”的本质含义 <a class="header-anchor" href="#_2-7-段地址-×16-偏移地址-物理地址-的本质含义" aria-label="Permalink to &quot;2.7 “段地址 ×16 + 偏移地址 = 物理地址”的本质含义&quot;">​</a></h2><p>注意, 这里讨论的是 8086CPU 段地址和偏移地址的本质含义, 而不是为了解决具体的问题而在本质含义之上引申出来的更高级的逻辑意义。不管以多少种不同的逻辑意义去看待 &quot;段地址 x16+偏移地址 = 物理地址&quot; 的寻址模式, 一定要清楚地知道它的本质含义, 这样才能更灵活地利用它来分析、解决问题。如果只拘泥于某一种引申出来的逻辑含义, 而模糊本质含义的话, 将从意识上限制对这种寻址功能的灵活应用。</p><p>&quot;段地址 x16+偏移地址 = 物理地址&quot; 的本质含义是: CPU 在访问内存时, 用一个基础地址(段地址 x16)和一个相对于基础地址的偏移地址相加, 给出内存单元的物理地址。</p><p>更一般地说,8086CPU 的这种寻址功能是 &quot;<strong>基础地址+偏移地址 = 物理地址</strong>&quot; 寻址模式的一种具体实现方案。8086CPU 中, 段地址 x16 可看作是基础地址。</p><p>第一个比喻说明 &quot;基础地址+偏移地址 = 物理地址&quot; 的思想。</p><p>比如说，学校、体育馆、图书馆同在一条笔直的单行路上（参考图 2.8），学校位于路的起点（从路的起点到学校距离是 0 米）。</p><p><img src="`+b+'" alt="image-20251014171828847"></p><p>你要去图书馆, 问我那里的地址, 我可以用两种方式告诉你图书馆的地址:</p><p>（1）从学校走 2826m 到图书馆。这 2826m 可以认为是图书馆的物理地址。</p><p>（2）从学校走 2000m 到体育馆, 从体育馆再走 826m 到图书馆。第一个距离 2000m, 是相对于起点的基础地址, 第二个距离 826m 是相对于基础地址的偏移地址(以基础地址为起点的地址)。</p><p>第一种方式是直接给出物理地址 2826m, 而第二种方式是用基础地址和偏移地址相加来得到物理地址的。</p><p>第二个比喻进一步说明 &quot;段地址 x16+偏移地址 = 物理地址&quot; 的思想。</p><p>我们为上面的例子加一些限制条件，比如，只能通过纸条来互相通信，你问我图书馆的地址我只能将它写在纸上告诉你。显然，我必须有一张可以容纳 4 位数据的纸条，才能写下 2826 这个数据。</p><p><img src="'+u+'" alt="image-20251014171959420"></p><p>可不巧的是, 我没有能容纳 4 位数据的纸条, 仅有两张可以容纳 3 位数据的纸条。这样我只能以这种方式告诉你 2826 这个数据。</p><p><img src="'+h+'" alt="image-20251014172035685"></p><p>在第一张纸上写上 200（段地址），在第二张纸上写上 826（偏移地址）。假设我们事前对这种情况又有过相关的约定：你得到这两张纸后，做这样的运算：200（段地址）x 10 + 826（偏移地址）= 2826（物理地址）。</p><p>8086CPU 就是这样一个只能提供两张 3 位数据纸条的 CPU。</p><h2 id="_2-8-段的概念" tabindex="-1">2.8 段的概念 <a class="header-anchor" href="#_2-8-段的概念" aria-label="Permalink to &quot;2.8 段的概念&quot;">​</a></h2><p>我们注意到，&quot;段地址&quot; 这个名称中包含着 &quot;段&quot; 的概念。这种说法可能对一些学习者产生了误导，使人误以为内存被划分成了一个一个的段，每一个段有一个段地址。如果我们在一开始形成了这种认识, 将影响以后对汇编语言的深入理解和灵活应用。</p><p>其实, 内存并没有分段, 段的划分来自于 CPU, 由于 8086CPU 用 &quot;基础地址(段地址 x16)+偏移地址 = 物理地址&quot; 的方式给出内存单元的物理地址, 使得我们可以用分段的方式来管理内存。如图 2.9 所示, 我们可以认为: 地址 10000H ~ 100FFH 的内存单元组成一个段, 该段的起始地址(基础地址)为 10000H, 段地址为 1000H, 大小为 100H; 我们也可以认为地址 10000H ~ 1007FH、10080H ~100FFH 的内存单元组成两个段, 它们的起始地址(基础地址)为: 10000H 和 10080H, 段地址为: 1000H 和 1008H, 大小都为 80H。</p><p><img src="'+g+`" alt="image-20251014172314984"></p><p>以后, 在编程时可以根据需要, 将若干地址连续的内存单元看作一个段, 用段地址 x16 定位段的起始地址(基础地址), 用偏移地址定位段中的内存单元。有两点需要注意: 段地址 x16 必然是 16 的倍数, 所以一个段的起始地址也一定是 16 的倍数; 偏移地址为 16 位,16 位地址的寻址能力为 64KB, 所以一个段的长度最大为 64KB。</p><h2 id="_2-a-内存单元地址小结" tabindex="-1">2.A 内存单元地址小结 <a class="header-anchor" href="#_2-a-内存单元地址小结" aria-label="Permalink to &quot;2.A 内存单元地址小结&quot;">​</a></h2><p>CPU 访问内存单元时，必须向内存提供内存单元的物理地址。8086CPU 在内部用段地址和偏移地址移位相加的方法形成最终的物理地址。</p><ul><li>（1）观察下面的地址, 你有什么发现?</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>物理地址   段地址  偏移地址</span></span>
<span class="line"><span>21F60H   2000H   1F60H </span></span>
<span class="line"><span>         2100H   0F60H</span></span>
<span class="line"><span>         21F0H   0060H</span></span>
<span class="line"><span>         21F6H   0000H</span></span>
<span class="line"><span>         1F00H   2F60H</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>结论: CPU 可以用不同的段地址和偏移地址形成同一个物理地址。</p><p>比如 CPU 要访问 21F60H 单元, 则它给出的段地址 SA 和偏移地址 EA 满足 SAX16+EA = 21F60H 即可。</p><ul><li>（2）如果给定一个段读地址，仅通过变化偏移地址来进行寻址，最多可定位读多少个内存单元？</li></ul><p>结论：偏移地址 16 位，变化范围为 0~FFFFH，仅用偏移地址来寻址最读多可寻 64KB 读个内存单元。</p><p>比如给定段地址 1000H，用偏移地址寻址，CPU 的寻址范围为：10000H~1FFFFH。</p><p>在 8086PC 机中，存储单元的地址用两个元素来描述，即段地址和偏移地址。</p><p>&quot;数据在 21F60H 内存单元中。&quot; 这句话对于 8086PC 机一般不这样讲，取而代之的是两种类似的说法：① 数据存在内存 2000:1F60 单元中；② 数据存在内存的 2000H 段中的 1F60H 单元中。这两种描述都表示 &quot;数据在内存 21F60H 单元中&quot;。</p><p>可以根据需要，将地址连续、起始地址为 16 的倍数的一组内存单元定义为一个段。</p><h2 id="_2-b-检测点-2-2" tabindex="-1">2.B 检测点 2.2 <a class="header-anchor" href="#_2-b-检测点-2-2" aria-label="Permalink to &quot;2.B 检测点 2.2&quot;">​</a></h2><p>(1)给定段地址为 0001H，仅通过变化偏移地址寻址，CPU 的寻址范围为 00010H 到 1000FH</p><p>解析：偏移地址变化范围为 0~FFFFH，寻址范围为段地址 ×16 + 偏移地址</p><p>(2)有一数据存放在内存 20000H 单元中，现给定段地址为 SA，若想用偏移地址寻到此单元。则 SA 应满足的条件是：最小为 1001H，最大为 2000H。</p><p>（提示，反过来思考一下，当段地址给定为多少，CPU 无论怎么变化偏移地址都无法寻到 20000H 单元？）</p><p>解析：段地址的最大值，可以用物理地址减去偏移地址的最小值；同理，段地址的最小值，可以用物理地址减去偏移地址的最大值。</p><p>20000H - 0H / 16 = 2000H</p><p>20000H - FFFFH = 10001H 不能被 16 整除，取 10010H / 16 = 1001H</p><p>当 SA &lt;=1000H 或 SA&gt; 2000H 时，CPU 无论怎么变化偏移地址都无法寻到 20000H 单元。</p><h2 id="_2-9-段寄存器" tabindex="-1">2.9 段寄存器 <a class="header-anchor" href="#_2-9-段寄存器" aria-label="Permalink to &quot;2.9 段寄存器&quot;">​</a></h2><p>我们前面讲到,8086CPU 在访问内存时要由相关部件提供内存单元的段地址和偏移地址, 送入地址加法器合成物理地址。这里, 需要看一下, 是什么部件提供段地址。段地址在 8086CPU 的段寄存器中存放。8086CPU 有 4 个段寄存器: CS、DS、SS、ES。当 8086CPU 要访问内存时由这 4 个段寄存器提供内存单元的段地址。本章中只看一下 CS。</p><h2 id="_2-10-cs-和-ip" tabindex="-1">2.10 CS 和 IP <a class="header-anchor" href="#_2-10-cs-和-ip" aria-label="Permalink to &quot;2.10 CS 和 IP&quot;">​</a></h2><h3 id="_2-10-1-两个寄存器的作用" tabindex="-1">2.10.1 两个寄存器的作用 <a class="header-anchor" href="#_2-10-1-两个寄存器的作用" aria-label="Permalink to &quot;2.10.1 两个寄存器的作用&quot;">​</a></h3><p>CS 和 IP 是 8086CPU 中两个最关键的寄存器, 它们指示了 CPU 当前要读取指令的地址。<strong>CS 为代码段寄存器</strong>, <strong>IP 为指令指针寄存器</strong>, 从名称上我们可以看出它们和指令的关系。</p><p>在 8086PC 机中, 任意时刻, 设 CS 中的内容为 M, IP 中的内容为 N, 8086CPU 将从内存 Mx16+N 单元开始, 读取一条指令并执行。也可以这样表述: 8086 机中, 任意时刻, CPU <strong>将 CS: IP 指向的内容当作指令执行</strong>。</p><p>图 2.10 展示了 8086CPU 读取、执行指令的工作原理(图中只包括了和所要说明的问题密切相关的部件, 图中数字都为十六进制)。</p><p><img src="`+P+`" alt="image-20251014201546690"></p><p>图 2.10 说明如下：</p><p>（1）8086CPU 当前状态：CS 中的内容为 2000H，IP 中的内容为 0000H；</p><p>（2）内存 20000H~20009H 单元存放着可执行的机器码；</p><p>（3）内存 20000H~20009H 单元中存放的机器码对应的汇编指令如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址： 20000H~20002H， 内容： B8 23 01，长度： 3Byte，对应汇编指令：mov ax，0123H</span></span>
<span class="line"><span>地址： 20003H~20005H， 内容： BB 03 00，长度： 3Byte，对应汇编指令：mov bx，0003H</span></span>
<span class="line"><span>地址： 20006H~20007H， 内容：    89 D8，长度： 2Byte，对应汇编指令：mov ax，bx</span></span>
<span class="line"><span>地址： 20008H~20009H， 内容：    01 D8，长度： 2Byte，对应汇编指令：add ax，bx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_2-10-2-执行指令实例-1" tabindex="-1">2.10.2 执行指令实例 1 <a class="header-anchor" href="#_2-10-2-执行指令实例-1" aria-label="Permalink to &quot;2.10.2 执行指令实例 1&quot;">​</a></h3><p>下面的一组图(图 2.11~图 2.19), 以图 2.10 描述的情况为初始状态, 展示了 8086CPU 读取、执行一条指令的过程。注意每幅图中发生的变化(下面对 8086CPU 的描述, 是在逻辑结构、宏观过程的层面上进行的, 目的是使读者对 CPU 工作原理有一个清晰、直观的认识, 为汇编语言的学习打下基础。其中隐蔽了 CPU 的物理结构以及具体的工作细节)。</p><p><img src="`+C+'" alt="image-20251014201902680"></p><p><img src="'+H+'" alt="image-20251014201920364"></p><p><img src="'+x+'" alt="image-20251014201932356"></p><p><img src="'+v+'" alt="image-20251014201944020"></p><p><img src="'+A+'" alt="image-20251014201959757"></p><p><img src="'+B+'" alt="image-20251014202016628"></p><p><img src="'+U+'" alt="image-20251014202033492"></p><p><img src="'+q+'" alt="image-20251014202046408"></p><p><img src="'+I+'" alt="image-20251014202102476"></p><h3 id="_2-10-3-执行指令实例-2" tabindex="-1">2.10.3 执行指令实例 2 <a class="header-anchor" href="#_2-10-3-执行指令实例-2" aria-label="Permalink to &quot;2.10.3 执行指令实例 2&quot;">​</a></h3><p>下面的一组图(图 2.20~图 2.26), 以图 2.19 的情况为初始状态, 展示了 8086CPU 继续读取、执行 3 条指令的过程。注意 IP 的变化(下面的描述中, 隐蔽了读取每条指令的细节)。</p><p><img src="'+k+'" alt="image-20251014202431149"></p><p><img src="'+X+'" alt="image-20251014202445709"></p><p><img src="'+y+'" alt="image-20251014202457284"></p><p><img src="'+S+'" alt="image-20251014202510596"></p><p><img src="'+E+'" alt="image-20251014202528907"></p><p><img src="'+F+'" alt="image-20251014202547100"></p><p><img src="'+_+`" alt="image-20251014202606213"></p><h3 id="_2-10-4-工作过程总结" tabindex="-1">2.10.4 工作过程总结 <a class="header-anchor" href="#_2-10-4-工作过程总结" aria-label="Permalink to &quot;2.10.4 工作过程总结&quot;">​</a></h3><p>通过上面的过程展示,8086CPU 的工作过程可以简要描述如下。</p><p>（1）从 CS: IP 指向的内存单元读取指令，读取的指令进入指令缓冲器；</p><p>（2）IP = IP+所读取指令的长度，从而指向下一条指令；</p><p>（3）执行指令。转到步骤（1），重复这个过程。</p><p>在 8086CPU 加电启动或复位后（即 CPU 刚开始工作时）CS 和 IP 被设置为 CS = FFFFH，IP = 0000H，即在 8086PC 机刚启动时，CPU 从内存 FFFF0H 单元中读取指令执行，FFFF0H 单元中的指令是 8086PC 机开机后执行的第一条指令。</p><p>现在，我们更清楚了 CS 和 IP 的重要性，它们的内容提供了 CPU 要执行指令的地址。</p><p>我们在第 1 张中了解过，指令和数据没有任何区别，都是二进制信息，CPU 在工作的时候把有的信息看作指令，有的信息看作数据。现在，如果提出一个问题：CPU 根据什么将内存中的信息看作指令？如何回答？我们可以说，CPU 将 CS: IP 指向的内存单元中的内容看作指令，因为，在任何时候，CPU 将 CS、IP 中的内容当作指令的段地址和偏移地址，用它们合成指令的物理地址，到内存中读取指令码，执行。如果说，内存中的一段信息曾被 CPU 执行过的话，那么，它所在的内存单元必然被 CS: IP 指向过。</p><h2 id="_2-11-修改-cs、ip-的指令" tabindex="-1">2.11 修改 CS、IP 的指令 <a class="header-anchor" href="#_2-11-修改-cs、ip-的指令" aria-label="Permalink to &quot;2.11 修改 CS、IP 的指令&quot;">​</a></h2><p>在 CPU 中，程序员能够用指令读写的部件只有寄存器，程序员可以通过改变寄存器中的内容实现对 CPU 的控制。CPU 从何处执行指令是由 CS、IP 中的内容决定的，程序员可以通过改变 CS、IP 中的内容来控制 CPU 执行目标指令。</p><p>我们如何改变 CS、IP 的值呢？显然，8086CPU 必须提供相应的指令。我们如何修改 AX 中的值？可以用 mov 指令，如 mov ax，123 将 ax 中的值设为 123，显然，我们也可以用同样的方法设置其他寄存器的值，如 mov bx，123，mov cx，123，mov dx，123 等。其实，8086CPU 大部分寄存器的值，都可以用 mov 指令来改变，mov 指令被称为传送指令。</p><p>但是，mov 指令不能用于设置 CS、IP 的值，原因很简单，因为 8086CPU 没有提供这样的功能。8086CPU 为 CS、IP 提供了另外的指令来改变它们的值。能够改变 CS、IP 的内容的指令被统称为转移指令（我们以后会深入研究）。我们现在介绍一个最简单的可以修改 CS、IP 的指令：jmp 指令。</p><p>若想同时修改 CS、IP 的内容，可用形如 &quot;jmp 段地址：偏移地址&quot; 的指令完成，如：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jmp 2AE3:3 ;执行后：CS=2AE3H，IP=0003H，CPU将从2AE33H处读取指令。</span></span>
<span class="line"><span>jmp 3:0B16 ;执行后：CS=0003H，IP=0B16H，CPU将从00B46H 处读取指令。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>&quot;jmp 段地址：偏移地址&quot; 指令的功能为：用指令中给出的段地址修改 CS，偏移地址修改 IP。</p><p>若想仅修改 IP 的内容，可用形如 &quot;jmp 某一合法寄存器&quot; 的指令完成，如:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jmp ax  ;指令执行前: ax=1000H, CS=2000H, IP=0003H</span></span>
<span class="line"><span>        ;指令执行后: ax=1000H, CS=2000H, IP=1000H</span></span>
<span class="line"><span>jmp bx  ;指令执行前: bx=0B16H, CS=2000H, IP=0003H</span></span>
<span class="line"><span>        ;指令执行后: bx=0B16H, CS=2000H, IP=0B16H</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>&quot;jmp 某一合法寄存器&quot; 指令的功能为: 用寄存器中的值修改 IP。jmp ax, 在含义上好似: mov IP, ax。</p><p>注意, 我们在适当的时候, 会用已知的汇编指令的语法来描述新学的汇编指令的功能。采用一种 &quot;用汇编解释汇编&quot; 的方法来使读者更好地理解汇编指令的功能, 这样做有助于读者进行知识的相互融会。要强调的是, 我们是用 &quot;已知的汇编指令的语法&quot; 进行描述, 并不是用 &quot;已知的汇编指令&quot; 来描述, 比如, 我们用 mov IP, ax 来描述 jmp ax, 并不是说真有 mov IP, ax 这样的指令, 而是用 mov 指令的语法来说明 jmp 指令的功能。 我们可以用同样的方法描述 jmp 3:01B6 的功能: jmp 3:01B6 在含义上好似 mov CS,3 读 mov IP,01B6。</p><h3 id="问题-2-3" tabindex="-1">问题 2.3 <a class="header-anchor" href="#问题-2-3" aria-label="Permalink to &quot;问题 2.3&quot;">​</a></h3><p>内存中存放的机器码和对应的汇编指令情况如图 2.27 所示, 设 CPU 初始状态: CS = 2000H, IP = 0000H, 请写出指令执行序列。思考后看分析。</p><p><img src="`+f+`" alt="image-20251015091708381"></p><p>分析：</p><p>（1）当前 CS = 2000H，IP = 0000H，则 CPU 从内存 2000HX16+0 = 20000H 处读取指令，读入的指令是： B8 22 66（mov ax，6622H），读入后 IP = IP+3 = 0003H；</p><p>（2）指令执行后，CS = 2000H，IP = 0003H，则 CPU 从内存 2000HX16+0003H = 20003H 处读取指令，读入的指令是：EA 03 00 00 10（jmp1000:0003），读入后 IP = IP+5 = 0008H;</p><p>（3） 指令执行后，CS = 1000H，IP = 0003H（上一步是 jmp 指令，这里直接被修改了），则 CPU 从内存 1000HX16+0003H = 10003H 处读取指令，读入的指令是：B8 00 00（mov ax，0000），读入后 IP = IP+3 = 0006H；此时 ax 中存放的数据为 0000H；</p><p>（4） 指令执行后，CS = 1000H，IP = 0006H，则 CPU 从内存 1000HX16+0006H = 10006H 处读取指令，读入的指令是： 8B D8（mov bx，ax）， 读入后 IP = IP+2 = 0008H；这里将 ax 中的数据存到 bx 中，此时 bx 中数据为 0000H；</p><p>（5） 指令执行后，CS = 1000H，IP = 0008H，则 CPU 从内存 1000HX16+0008H = 10008H 处读取指令， 读入的指令是： FF E3（jmp bx），读入后 IP = IP+2 = 000AH；由于 bx 中数据为 0000H，所以这一步执行完毕，IP 会直接等于 0000H；</p><p>（6） 指令执行后，CS = 1000H，IP = 0000H，CPU 从内存 10000H 处读取指令……</p><p>经分析后, 可知指令执行序列为:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,6622H  ; （1）</span></span>
<span class="line"><span>jmp 1000:3    ; （2） </span></span>
<span class="line"><span>mov ax,0000   ; （3）</span></span>
<span class="line"><span>mov bx,ax     ; （4）</span></span>
<span class="line"><span>jmp bx        ; （5）</span></span>
<span class="line"><span>mov ax,0123H  ; （6）</span></span>
<span class="line"><span>转到第3步执行  ; （7）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="_2-12-代码段" tabindex="-1">2.12 代码段 <a class="header-anchor" href="#_2-12-代码段" aria-label="Permalink to &quot;2.12 代码段&quot;">​</a></h2><p>前面讲过, 对于 8086PC 机, 在编程时, 可以根据需要, 将一组内存单元定义为一个段。我们可以将长度为 N(N &lt; 64KB)的一组代码, 存在一组地址连续、起始地址为 16 的倍数的内存单元中, 我们可以认为, 这段内存是用来存放代码的, 从而定义了一个代码段。</p><p>比如, 将:</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,0000  ; (B8 00 00)</span></span>
<span class="line"><span>add ax,0123H ; (05 23 01)</span></span>
<span class="line"><span>mov bx,ax    ; (8B D8)</span></span>
<span class="line"><span>jmp bx       ; (FF E3)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>这段长度为 10 个字节的指令, 存放在 123B0H~123B9H 的一组内存单元中, 我们就可以认为, 123B0H~123B9H 这段内存是用来存放代码的, 是一个代码段, 它的段地址为 123BH, 长度为 10 个字节。</p><p>如何使得代码段中的指令被执行呢?将一段内存当作代码段, 仅仅是我们在编程时的一种安排, CPU 并不会由于这种安排, 就自动地将我们定义的代码段中的指令当作指令来执行。CPU 只认被 CS: IP 指向的内存单元中的内容为指令。所以, 要让 CPU 执行我们放在代码段中的指令, 必须要将 CS: IP 指向所定义的代码段中的第一条指令的首地址。</p><p>对于上面的例子, 我们将一段代码存放在 123B0H~123B9H 内存单元中, 将其定义为代码段, 如果要让这段代码得到执行, 可设 CS = 123BH、IP = 0000H。</p><h2 id="_2-c-小结与检测点" tabindex="-1">2.C 小结与检测点 <a class="header-anchor" href="#_2-c-小结与检测点" aria-label="Permalink to &quot;2.C 小结与检测点&quot;">​</a></h2><h3 id="_2-9-2-12-小结" tabindex="-1">2.9-2.12 小结 <a class="header-anchor" href="#_2-9-2-12-小结" aria-label="Permalink to &quot;2.9-2.12 小结&quot;">​</a></h3><p>（1）段地址在 8086CPU 的段寄存器中存放。当 8086CPU 要访问内存时，由段寄存器提供内存单元的段地址。8086CPU 有 4 个段寄存器，其中 CS 用来存放指令的段地址。</p><p>（2）CS 存放指令的段地址，IP 存放指令的偏移地址。8086 机中，任意时刻，CPU 将 CS: IP 指向的内容当作指令执行。</p><p>（3）8086CPU 的工作过程：</p><p>​ ① 从 CS: IP 指向的内存单元读取指令，读取的指令进入指令缓冲器；</p><p>​ ②IP 指向下一条指令；</p><p>​ ③ 执行指令。（转到步骤 ①，重复这个过程。）</p><p>（4）8086CPU 提供转移指令修改 CS、IP 的内容。</p><h4 id="检测点-2-3" tabindex="-1">检测点 2.3 <a class="header-anchor" href="#检测点-2-3" aria-label="Permalink to &quot;检测点 2.3&quot;">​</a></h4><p>下面的 3 条指令执行后，CPU 几次修改 IP？都是在什么时候？最后 IP 中的值是多少？</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mov ax,bx</span></span>
<span class="line"><span>sub ax, ax</span></span>
<span class="line"><span>jmp ax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>解析：一共修改了 4 次。</p><p>读取 mov ax, bx 指令后，第一次修改 IP</p><p>读取 sub ax, ax 指令后，第二次修改 IP</p><p>读取 jmp ax 指令后，第三次修改 IP</p><p>执行 jmp ax 指令时，第四次修改 IP，最后 IP = ax = 0</p>`,205)])])}const M=s(D,[["render",w]]);export{z as __pageData,M as default};
